/**
 * Fahad Gsn — Password verification using Web Crypto API (PBKDF2-SHA256)
 *
 * Format stored in DB: "pbkdf2:<salt_hex>:<hash_hex>"
 * Matches the format generated by scripts/seed-admin.mjs
 *
 * Note: uses `as unknown as BufferSource` to avoid @cloudflare/workers-types
 * conflict with the built-in dom lib's Uint8Array type.
 */

const ITERATIONS = 100_000
const KEY_LENGTH = 32 // 256 bits

function hexToUint8Array(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2)
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.slice(i, i + 2), 16)
  }
  return bytes
}

function uint8ArrayToHex(arr: Uint8Array): string {
  return Array.from(arr)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
}

// Workaround: @cloudflare/workers-types redefines Uint8Array incompatibly with dom lib.
// Cast through unknown to satisfy both type systems.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toBufferSource(u8: Uint8Array): any { return u8 }

/**
 * Verify a plaintext password against a stored PBKDF2 hash.
 * Uses constant-time HMAC comparison to prevent timing attacks.
 */
export async function verifyPassword(password: string, stored: string): Promise<boolean> {
  try {
    const parts = stored.split(':')
    if (parts.length !== 3 || parts[0] !== 'pbkdf2') return false
    const [, saltHex, expectedHashHex] = parts

    const encoder = new TextEncoder()
    const salt = hexToUint8Array(saltHex)
    const passwordBytes = encoder.encode(password)

    const keyMaterial = await globalThis.crypto.subtle.importKey(
      'raw',
      toBufferSource(passwordBytes),
      'PBKDF2',
      false,
      ['deriveBits'],
    )

    const derivedBits = await globalThis.crypto.subtle.deriveBits(
      { name: 'PBKDF2', salt: toBufferSource(salt), iterations: ITERATIONS, hash: 'SHA-256' },
      keyMaterial,
      KEY_LENGTH * 8,
    )

    const actualHashHex = uint8ArrayToHex(new Uint8Array(derivedBits))

    // Constant-time comparison using HMAC with a zero key
    const zeroKey = new Uint8Array(32)
    const k = await globalThis.crypto.subtle.importKey(
      'raw',
      toBufferSource(zeroKey),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign'],
    )
    const enc = new TextEncoder()
    const [s1, s2] = await Promise.all([
      globalThis.crypto.subtle.sign('HMAC', k, toBufferSource(enc.encode(actualHashHex))),
      globalThis.crypto.subtle.sign('HMAC', k, toBufferSource(enc.encode(expectedHashHex))),
    ])
    const a1 = new Uint8Array(s1)
    const a2 = new Uint8Array(s2)
    return a1.length === a2.length && a1.every((v, i) => v === a2[i])
  } catch {
    return false
  }
}
